plugins.install_cmd:
cat > ~/.claude/mcp.json <<'EOF'
{
  "mcpServers": {
    "vault": {
      "type": "http",
      "url": "https://longku-vault.zeabur.app/mcp",
      "headers": {
        "Authorization": "Bearer <YOUR_VAULT_TOKEN>"
      }
    }
  }
}
EOF
# 把 <YOUR_VAULT_TOKEN> 换成你的 Vault token, 重启 Claude Code 生效
